-- table audit_log ON audit_log
CREATE TABLE audit_log (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      event TEXT NOT NULL,
      at TEXT NOT NULL,
      trace_id TEXT,
      data TEXT
    );

-- table candidates ON candidates
CREATE TABLE candidates (
      id TEXT PRIMARY KEY,
      data TEXT NOT NULL,
      status TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      canonical_text TEXT NOT NULL DEFAULT ''
    );

-- table edges ON edges
CREATE TABLE edges (
      from_node TEXT NOT NULL,
      to_node TEXT NOT NULL,
      relation TEXT NOT NULL,
      weight REAL NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL,
      PRIMARY KEY (from_node, to_node, relation)
    );

-- table hq_memory_sync ON hq_memory_sync
CREATE TABLE hq_memory_sync (
      id TEXT PRIMARY KEY, revision INTEGER NOT NULL, change_id TEXT NOT NULL, data TEXT
    );

-- table hq_memory_sync_clock ON hq_memory_sync_clock
CREATE TABLE hq_memory_sync_clock (
      id INTEGER PRIMARY KEY CHECK(id = 1), epoch TEXT NOT NULL, revision INTEGER NOT NULL
    );

-- table memories ON memories
CREATE TABLE memories (
      id TEXT PRIMARY KEY,
      data TEXT NOT NULL,
      status TEXT NOT NULL,
      kind TEXT NOT NULL,
      scope TEXT NOT NULL,
      legacy_scope TEXT,
      importance REAL NOT NULL,
      confidence REAL NOT NULL,
      freshness REAL NOT NULL,
      updated_at TEXT NOT NULL,
      created_at TEXT NOT NULL,
      audience TEXT,
      tags TEXT,
      owner_session_id TEXT,
      canonical_text TEXT NOT NULL DEFAULT ''
    , unicode_text TEXT);

-- table memories_fts ON memories_fts
CREATE VIRTUAL TABLE memories_fts USING fts5(
        text, tags, audience, content='memories', content_rowid='rowid'
      );

-- table memories_fts_config ON memories_fts_config
CREATE TABLE 'memories_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;

